// Politik – Internationale Politik / Welt
(window.SLIDES = window.SLIDES || []).push(
  // ───────── Europäische Union ─────────
  { id: "pwe-001", cat: "politik", topic: "EU-Institutionen", type: "fact", emoji: "🇪🇺", level: 1,
    title: "Wer macht was in der EU?",
    text: "**Kommission** schlägt Gesetze vor und überwacht ihre Einhaltung. **Parlament** und **Rat der EU** (Fachminister) beschließen sie gemeinsam. **Europäischer Rat** (Staats- und Regierungschefs) setzt die große Richtung. **EuGH** legt das Recht verbindlich aus.",
    more: "Merkhilfe: Kommission = Motor (Initiativrecht), Parlament + Rat = zwei Kammern des Gesetzgebers, Europäischer Rat = Strategie-Chefetage, EuGH = Schiedsrichter. Ungewöhnlich: Das Parlament darf selbst keine Gesetze vorschlagen – es kann die Kommission nur dazu auffordern." },
  { id: "pwe-002", cat: "politik", topic: "EU-Institutionen", type: "quiz", emoji: "🏛️", level: 1,
    q: "Welche EU-Institution hat (fast) das alleinige Recht, Gesetze vorzuschlagen?",
    options: ["Europäisches Parlament", "Europäische Kommission", "Europäischer Rat", "Europäischer Gerichtshof"], answer: 1,
    explain: "Die Kommission hat das Initiativmonopol. Parlament und Rat können sie nur auffordern, einen Vorschlag zu machen – anders als der Bundestag, dessen Fraktionen selbst Gesetzentwürfe einbringen können." },
  { id: "pwe-003", cat: "politik", topic: "EU-Institutionen", type: "truefalse", emoji: "🤔", level: 1,
    q: "Der Europarat in Straßburg ist ein Organ der Europäischen Union.",
    answer: false,
    explain: "Falsch. Der **Europarat** ist eine eigene Organisation (46 Mitglieder, gegründet 1949), Hüter der Menschenrechtskonvention mit dem Gerichtshof für Menschenrechte. Nicht verwechseln mit dem **Europäischen Rat** (EU-Gipfel) und dem **Rat der EU** (Ministerrat)." },
  { id: "pwe-004", cat: "politik", topic: "EU-Institutionen", type: "flashcard", emoji: "⚖️", level: 3,
    term: "Qualifizierte Mehrheit (Rat der EU)",
    def: "Doppelte Mehrheit: mindestens 55 % der Mitgliedstaaten (15 von 27), die zusammen mindestens 65 % der EU-Bevölkerung vertreten. Standardverfahren für die meisten Gesetze.",
    example: "Eine Sperrminorität braucht mindestens 4 Staaten mit über 35 % der Bevölkerung – große Länder allein können nichts blockieren." },
  { id: "pwe-005", cat: "politik", topic: "EU-Institutionen", type: "number", emoji: "🗳️", level: 1,
    value: "720", label: "Abgeordnete im Europäischen Parlament (Wahl 2024)",
    text: "Gewählt alle 5 Jahre direkt von den Bürgern. Deutschland stellt mit 96 die meisten Sitze, Malta, Zypern und Luxemburg je 6.",
    more: "Die Verteilung ist **degressiv proportional**: Kleine Staaten haben pro Kopf deutlich mehr Gewicht. Ein maltesischer Abgeordneter vertritt rund 90.000 Menschen, ein deutscher rund 870.000 – ein bewusster Kompromiss zwischen Bürger- und Staatengleichheit." },
  { id: "pwe-006", cat: "politik", topic: "EU-Institutionen", type: "quiz", emoji: "👩‍⚖️", level: 2,
    q: "Was ist die wichtigste Aufgabe des Europäischen Gerichtshofs (EuGH) in Luxemburg?",
    options: ["Kriegsverbrechen ahnden", "Streit zwischen beliebigen Staaten der Welt schlichten", "Menschenrechtsbeschwerden gegen Russland prüfen", "EU-Recht einheitlich auslegen und durchsetzen"], answer: 3,
    explain: "Über **Vorabentscheidungsverfahren** fragen nationale Gerichte den EuGH, wie EU-Recht zu verstehen ist. Seine Urteile gelten überall in der EU – so entstand z. B. der Vorrang des EU-Rechts vor nationalem Recht (Costa/ENEL, 1964)." },
  { id: "pwe-007", cat: "politik", topic: "EU-Institutionen", type: "fact", emoji: "🔒", level: 2,
    title: "Einstimmigkeit: die Achillesferse der EU",
    text: "In Außen- und Sicherheitspolitik, bei Steuern, Erweiterung und dem langfristigen Haushalt braucht es Einstimmigkeit. Ein einziges Land kann blockieren – etwa Ungarn bei Ukraine-Hilfen oder Sanktionen.",
    more: "Darum wird über die **Passerelle-Klausel** diskutiert: Der Europäische Rat könnte einstimmig beschließen, künftig mit Mehrheit zu entscheiden. Kleinere Staaten fürchten jedoch, überstimmt zu werden. Einstimmigkeit schützt Souveränität – kostet aber Handlungsfähigkeit." },
  { id: "pwe-008", cat: "politik", topic: "Binnenmarkt", type: "flashcard", emoji: "🛒", level: 1,
    term: "Die vier Grundfreiheiten",
    def: "Freier Verkehr von **Waren, Dienstleistungen, Personen** und **Kapital** im EU-Binnenmarkt (seit 1993 vollendet). Kern der europäischen Integration.",
    example: "Ein deutscher Ingenieur kann ohne Arbeitserlaubnis in Spanien arbeiten; ein französischer Käse darf ohne Zoll in Polen verkauft werden." },
  { id: "pwe-009", cat: "politik", topic: "Binnenmarkt", type: "fact", emoji: "🌍", level: 2,
    title: "Der Brüssel-Effekt",
    text: "Weil der EU-Binnenmarkt mit rund 450 Mio. Konsumenten so groß ist, übernehmen Konzerne EU-Regeln oft weltweit – etwa die DSGVO beim Datenschutz oder USB-C als Ladestandard.",
    more: "Der Begriff stammt von der Juristin Anu Bradford. Logik: Eine globale Firma produziert lieber ein Produkt für alle als Sonderversionen. So exportiert die EU ihre Standards ohne Militärmacht – eine Form regulatorischer Macht, die oft als Beispiel für Europas Einfluss genannt wird." },
  { id: "pwe-010", cat: "politik", topic: "Euro", type: "number", emoji: "💶", level: 1,
    value: "21", label: "Euro-Länder seit 1. Januar 2026",
    text: "Bulgarien wurde zum 1.1.2026 das 21. Mitglied der Eurozone. Zuvor war Kroatien 2023 beigetreten. Das Bargeld gibt es seit 2002, als Buchgeld seit 1999.",
    more: "Nicht alle EU-Staaten haben den Euro: Dänemark hat eine vertragliche Ausnahme, Schweden, Polen, Tschechien, Ungarn und Rumänien erfüllen Kriterien nicht oder wollen (noch) nicht. Wer neu in die EU kommt, ist grundsätzlich zur Euro-Einführung verpflichtet." },
  { id: "pwe-011", cat: "politik", topic: "Euro", type: "whatif", emoji: "📉", level: 3,
    q: "Was passiert, wenn ein Euro-Land in eine schwere Krise gerät, aber nicht abwerten kann?",
    steps: ["Eigene Währung abwerten ist unmöglich", "Anpassung nur über Löhne und Preise", "Hohe Arbeitslosigkeit, Rezession", "Zinsen auf Staatsanleihen steigen", "Rettungsschirm (ESM) oder EZB greifen ein"],
    text: "Genau das erlebte Griechenland ab 2010. Eine Währungsunion ohne gemeinsame Fiskalpolitik verliert das Ventil Wechselkurs. Darum entstanden ESM-Kredite und das EZB-Versprechen „Whatever it takes“ (Draghi, 2012)." },
  { id: "pwe-012", cat: "politik", topic: "Schengen", type: "quiz", emoji: "🛂", level: 2,
    q: "Welches EU-Land gehört NICHT zum Schengen-Raum (Stand 2025)?",
    options: ["Irland", "Rumänien", "Kroatien", "Schweiz"], answer: 0,
    explain: "Irland bleibt wegen der gemeinsamen Reisezone mit Großbritannien draußen, Zypern wegen der Teilung. Rumänien und Bulgarien sind seit 2025 Vollmitglieder. Die Schweiz ist kein EU-Mitglied, aber im Schengen-Raum – wie Norwegen, Island und Liechtenstein." },
  { id: "pwe-013", cat: "politik", topic: "Schengen", type: "truefalse", emoji: "🚧", level: 1,
    q: "Schengen-Staaten dürfen keinesfalls wieder Grenzkontrollen einführen.",
    answer: false,
    explain: "Falsch. Bei ernsthafter Bedrohung der öffentlichen Ordnung sind vorübergehende Binnengrenzkontrollen erlaubt und müssen gemeldet werden. Deutschland kontrolliert seit September 2024 an allen Landgrenzen – Kritiker sehen darin eine Aushöhlung der Reisefreiheit." },
  { id: "pwe-014", cat: "politik", topic: "EU-Erweiterung", type: "order", emoji: "🧩", level: 2,
    q: "Bringe die Stationen der europäischen Integration in die richtige Reihenfolge.",
    items: ["Römische Verträge (EWG)", "Vertrag von Maastricht (EU)", "Osterweiterung um 10 Staaten", "Vertrag von Lissabon tritt in Kraft"],
    explain: "1957 Römische Verträge, 1992/93 Maastricht (Gründung der EU, Weg zum Euro), 2004 Osterweiterung (u. a. Polen, Baltikum), 2009 Lissabon (Ratspräsident, mehr Rechte fürs Parlament, Austrittsartikel 50)." },
  { id: "pwe-015", cat: "politik", topic: "EU-Erweiterung", type: "flashcard", emoji: "📋", level: 2,
    term: "Kopenhagener Kriterien",
    def: "Beitrittsbedingungen seit 1993: stabile Demokratie und Rechtsstaat mit Minderheitenschutz, funktionierende Marktwirtschaft, Fähigkeit, den gesamten EU-Rechtsbestand zu übernehmen.",
    example: "Die Türkei ist seit 1999 Kandidat, die Gespräche liegen wegen Rechtsstaatsdefiziten de facto auf Eis." },
  { id: "pwe-016", cat: "politik", topic: "EU-Erweiterung", type: "quiz", emoji: "🗺️", level: 2,
    q: "Welche Länder erhielten nach Russlands Invasion 2022 den EU-Kandidatenstatus?",
    options: ["Serbien und Montenegro", "Norwegen und Island", "Ukraine und Moldau", "Belarus und Armenien"], answer: 2,
    explain: "Im Juni 2022 wurden die Ukraine und Moldau Kandidaten, Georgien folgte im Dezember 2023. Serbien und Montenegro sind schon länger Kandidaten. Der Krieg hat Erweiterung wieder zur geopolitischen Frage gemacht." },
  { id: "pwe-017", cat: "politik", topic: "Brexit", type: "event", emoji: "🇬🇧", year: "2016", level: 1,
    title: "Brexit-Referendum",
    text: "Am 23. Juni 2016 stimmten 51,9 % der Briten für den Austritt aus der EU. Der Austritt wurde am 31. Januar 2020 vollzogen, die Übergangsphase endete am 31.12.2020.",
    more: "Rechtsgrundlage ist **Artikel 50 EU-Vertrag** – erstmals überhaupt genutzt. Größter Knackpunkt: die Grenze zwischen Irland und Nordirland, die wegen des Friedensabkommens von 1998 offen bleiben sollte. Lösung: Nordirland folgt teils weiter EU-Warenregeln (Windsor-Rahmen 2023)." },
  { id: "pwe-018", cat: "politik", topic: "Brexit", type: "whatif", emoji: "🚛", level: 2,
    q: "Was passiert, wenn ein Land den EU-Binnenmarkt und die Zollunion verlässt?",
    steps: ["Zollformulare und Ursprungsnachweise", "Kontrollen an der Grenze, Wartezeiten", "Höhere Handelskosten, weniger Handel", "Firmen verlagern Lager oder Sitz", "Wachstum fällt geringer aus"],
    text: "Auch ohne Zölle (das Handelsabkommen EU-UK hat Nullzölle) entstehen nichttarifäre Kosten. Großbritanniens Haushaltsbehörde OBR schätzte langfristig rund 4 % weniger Produktivität als bei EU-Verbleib." },
  { id: "pwe-019", cat: "politik", topic: "EU-Institutionen", type: "quiz", emoji: "🎯", level: 1,
    q: "Wer ist (Stand 2025) Präsidentin der Europäischen Kommission?",
    options: ["Roberta Metsola", "Kaja Kallas", "Christine Lagarde", "Ursula von der Leyen"], answer: 3,
    explain: "Ursula von der Leyen ist seit 2019 im Amt und startete im Dezember 2024 in ihre zweite Amtszeit. Metsola ist Parlamentspräsidentin, Kallas EU-Außenbeauftragte, Lagarde EZB-Präsidentin. Präsident des Europäischen Rats ist seit Dezember 2024 António Costa." },
  { id: "pwe-020", cat: "politik", topic: "Binnenmarkt", type: "truefalse", emoji: "💰", level: 1,
    q: "Der EU-Haushalt umfasst rund ein Drittel der Wirtschaftsleistung der EU.",
    answer: false,
    explain: "Falsch. Der EU-Haushalt liegt bei rund **1 % des Bruttonationaleinkommens** – die nationalen Haushalte sind 40- bis 50-mal größer. Größte Posten: Agrar- und Regionalförderung. Ausnahme war der Corona-Fonds NextGenerationEU mit gemeinsamen Schulden." },

  { id: "pwe-139", cat: "politik", topic: "EU-Institutionen", type: "order", emoji: "🔁", level: 2,
    q: "So entsteht ein EU-Gesetz (ordentliches Verfahren) – bringe die Schritte in die Reihenfolge.",
    items: ["Kommission legt einen Vorschlag vor", "Parlament legt seine Position fest", "Trilog: Parlament, Rat und Kommission verhandeln", "Parlament und Rat stimmen dem Kompromiss zu"],
    explain: "Die meisten Gesetze werden heute im informellen **Trilog** ausgehandelt, oft schon nach der ersten Lesung. Verordnungen gelten dann direkt in allen Staaten, Richtlinien müssen erst in nationales Recht umgesetzt werden." },

  // ───────── NATO ─────────
  { id: "pwe-021", cat: "politik", topic: "NATO", type: "fact", emoji: "🛡️", level: 1,
    title: "Artikel 5: Einer für alle",
    text: "Ein bewaffneter Angriff auf ein NATO-Mitglied gilt als Angriff auf alle. Jedes Mitglied leistet Beistand – mit Maßnahmen, „die es für erforderlich erachtet“, einschließlich Waffengewalt.",
    more: "Wichtiges Detail: Art. 5 verpflichtet nicht automatisch zum Kriegseintritt – jedes Land entscheidet über die Art der Hilfe. Die Abschreckung lebt deshalb von der **Glaubwürdigkeit**, vor allem der USA. Zweifel daran sind genau das, was Gegner ausnutzen wollen." },
  { id: "pwe-022", cat: "politik", topic: "NATO", type: "quiz", emoji: "🗽", level: 1,
    q: "Wann wurde der NATO-Bündnisfall nach Art. 5 bisher ausgerufen?",
    options: ["Nach der Krim-Annexion 2014", "Nach den Anschlägen vom 11. September 2001", "Im Kosovo-Krieg 1999", "Nach der russischen Invasion 2022"], answer: 1,
    explain: "Das einzige Mal: nach 9/11 – ausgerechnet zur Verteidigung der USA. Darauf folgte der Afghanistan-Einsatz. Bei 2014 und 2022 war kein Mitglied angegriffen; die Ukraine ist kein NATO-Mitglied. Polen u. a. beantragten aber Konsultationen nach **Art. 4**." },
  { id: "pwe-023", cat: "politik", topic: "NATO", type: "number", emoji: "🤝", level: 1,
    value: "32", label: "NATO-Mitglieder (seit 2024)",
    text: "Gegründet 1949 mit 12 Staaten. Finnland trat im April 2023 bei, Schweden im März 2024 – beide gaben dafür ihre jahrzehntelange Neutralität bzw. Bündnisfreiheit auf.",
    more: "Ironie der Geschichte: Russlands Krieg sollte die NATO zurückdrängen, verlängerte aber die NATO-Russland-Grenze durch Finnland um rund 1.300 km und machte die Ostsee fast zu einem „NATO-Binnenmeer“. Die Türkei und Ungarn hatten die Beitritte monatelang verzögert." },
  { id: "pwe-024", cat: "politik", topic: "NATO", type: "number", emoji: "💸", level: 2,
    value: "5 %", label: "Neues NATO-Ausgabenziel bis 2035 (Gipfel Den Haag 2025)",
    text: "3,5 % des BIP für Kernverteidigung plus 1,5 % für verteidigungsrelevante Infrastruktur und Resilienz. Das alte Ziel von 2 % stammte vom Gipfel in Wales 2014.",
    more: "Für Deutschland heißt 3,5 % grob über 150 Mrd. € pro Jahr. Ermöglicht wurde das 2025 durch eine Grundgesetzänderung: Verteidigungsausgaben über 1 % des BIP sind von der Schuldenbremse ausgenommen. Treiber: Bedrohung durch Russland und Druck aus Washington." },
  { id: "pwe-025", cat: "politik", topic: "NATO", type: "truefalse", emoji: "📜", level: 2,
    q: "Das 2-Prozent-Ziel der NATO ist ein rechtlich bindender Vertrag.",
    answer: false,
    explain: "Falsch. Ausgabenziele sind politische Selbstverpflichtungen von Gipfeln, kein Vertragsrecht. Sanktionen bei Verfehlung gibt es nicht – der Druck ist rein politisch. Lange erreichten nur wenige Staaten die 2 %, 2024 dann erstmals eine klare Mehrheit." },
  { id: "pwe-026", cat: "politik", topic: "NATO", type: "whatif", emoji: "⚔️", level: 3,
    q: "Was passiert, wenn Zweifel an der US-Beistandsgarantie wachsen?",
    steps: ["Abschreckung verliert Glaubwürdigkeit", "Gegner testen das Bündnis mit Provokationen", "Europäer rüsten selbst stärker auf", "Debatte über eigene nukleare Abschreckung", "Bündniszusammenhalt wird zur Kernfrage"],
    text: "Abschreckung wirkt nur, wenn der Gegner an sie glaubt. Deshalb sind Aussagen über Bündnistreue sicherheitspolitisch so heikel. Frankreich hat 2025 angeboten, über eine europäische Rolle seiner Atomwaffen zu sprechen." },
  { id: "pwe-027", cat: "politik", topic: "NATO", type: "flashcard", emoji: "🔄", level: 2,
    term: "Artikel 4 NATO-Vertrag",
    def: "Recht jedes Mitglieds, Konsultationen zu verlangen, wenn es seine Unversehrtheit, Unabhängigkeit oder Sicherheit bedroht sieht. Vorstufe vor Art. 5.",
    example: "Polen beantragte Art.-4-Konsultationen u. a. 2022 nach Russlands Invasion und 2025 nach dem Eindringen russischer Drohnen in seinen Luftraum." },

  // ───────── Vereinte Nationen ─────────
  { id: "pwe-028", cat: "politik", topic: "UN-Sicherheitsrat", type: "fact", emoji: "🌐", level: 1,
    title: "Der UN-Sicherheitsrat",
    text: "15 Mitglieder: 5 ständige mit Vetorecht (USA, Russland, China, Frankreich, Großbritannien) und 10 nichtständige, gewählt für 2 Jahre. Nur er kann für alle Staaten **verbindliche** Beschlüsse fassen – bis hin zu Sanktionen und Militäreinsätzen.",
    more: "Die P5 sind die Siegermächte des Zweiten Weltkriegs. Ein Beschluss braucht 9 Ja-Stimmen und kein Veto. Kritik: Die Struktur spiegelt 1945, nicht heute – Afrika, Indien, Brasilien, Deutschland oder Japan haben keinen ständigen Sitz. Eine Reform bräuchte die Zustimmung genau der P5." },
  { id: "pwe-029", cat: "politik", topic: "UN-Sicherheitsrat", type: "whatif", emoji: "✋", level: 1,
    q: "Was passiert, wenn ein ständiges Mitglied im Sicherheitsrat ein Veto einlegt?",
    steps: ["Resolution ist gescheitert, egal wie viele Ja", "Keine verbindlichen UN-Maßnahmen", "Seit 2022: Debattenpflicht in der UN-GV", "Ausweg: nicht bindende Resolution der GV", "Staaten handeln ggf. außerhalb der UN"],
    text: "Das Veto lähmt den Rat, wenn ein P5-Staat selbst Konfliktpartei ist oder Verbündete schützt – Russland bei der Ukraine, die USA oft bei Israel. Enthaltung zählt übrigens nicht als Veto." },
  { id: "pwe-030", cat: "politik", topic: "UN-Sicherheitsrat", type: "truefalse", emoji: "🙊", level: 2,
    q: "Enthält sich ein ständiges Mitglied, ist die Resolution blockiert.",
    answer: false,
    explain: "Falsch. Nach etablierter Praxis zählt nur ein Nein-Votum als Veto. Eine Enthaltung lässt die Resolution passieren, wenn 9 Ja-Stimmen erreicht sind. So kann eine Großmacht Distanz zeigen, ohne zu blockieren – etwa China und Russland 2011 bei der Libyen-Resolution 1973." },
  { id: "pwe-031", cat: "politik", topic: "Vereinte Nationen", type: "number", emoji: "🏳️", level: 1,
    value: "193", label: "Mitgliedstaaten der Vereinten Nationen",
    text: "Jüngstes Mitglied ist der Südsudan (2011). Gegründet 1945 mit 51 Staaten. Palästina und der Heilige Stuhl haben Beobachterstatus.",
    more: "Taiwan ist seit 1971 nicht mehr vertreten: Damals übertrug die Generalversammlung den China-Sitz (inkl. Sicherheitsratssitz) von der Republik China (Taiwan) an die Volksrepublik. Kosovo ist ebenfalls kein Mitglied – Russland und China würden einen Beitritt blockieren." },
  { id: "pwe-032", cat: "politik", topic: "Vereinte Nationen", type: "quiz", emoji: "🗳️", level: 1,
    q: "Wie wird in der UN-Generalversammlung abgestimmt?",
    options: ["Nach Bevölkerungsgröße gewichtet", "Jeder Staat hat eine Stimme", "Nach Beitragszahlungen gewichtet", "Nur die G20 sind stimmberechtigt"], answer: 1,
    explain: "Ein Staat, eine Stimme: Tuvalu zählt so viel wie China. Dafür sind die Beschlüsse der Generalversammlung meist nur **Empfehlungen** – politisch gewichtig, rechtlich nicht bindend. Verbindlich ist sie etwa beim UN-Haushalt." },
  { id: "pwe-033", cat: "politik", topic: "Vereinte Nationen", type: "fact", emoji: "📘", level: 1,
    title: "UN-Charta: Gewaltverbot als Kern",
    text: "Art. 2 Abs. 4 verbietet die Androhung oder Anwendung von Gewalt gegen andere Staaten. Nur zwei Ausnahmen: **Selbstverteidigung** (Art. 51) und Mandat des **Sicherheitsrats** nach Kapitel VII.",
    more: "Darum berufen sich Angreifer fast immer auf „Selbstverteidigung“ – auch Russland 2022. Völkerrechtlich trägt das nicht: Selbstverteidigung setzt einen bewaffneten Angriff voraus. Das Gewaltverbot gilt als Fundament der Nachkriegsordnung; seine offene Verletzung durch eine Vetomacht erschüttert das System." },
  { id: "pwe-034", cat: "politik", topic: "Vereinte Nationen", type: "event", emoji: "🖊️", year: "1945", level: 1,
    title: "Gründung der Vereinten Nationen",
    text: "Am 26. Juni 1945 unterzeichneten 50 Staaten in San Francisco die UN-Charta, am 24. Oktober 1945 trat sie in Kraft – heute der „Tag der Vereinten Nationen“.",
    more: "Die UN sind der zweite Versuch nach dem gescheiterten Völkerbund (1920), der weder die USA als Mitglied noch Durchsetzungsmacht hatte. Die Lehre: Großmächte einbinden – deshalb das Veto. Es soll verhindern, dass die UN gegen eine Großmacht Krieg führen und damit zerbrechen." },
  { id: "pwe-035", cat: "politik", topic: "UN-Sicherheitsrat", type: "quiz", emoji: "🔢", level: 2,
    q: "Wie viele Ja-Stimmen braucht eine Resolution im Sicherheitsrat (ohne Veto)?",
    options: ["8 von 15", "Alle 15", "10 von 15", "9 von 15"], answer: 3,
    explain: "9 von 15 Stimmen – und keines der fünf ständigen Mitglieder darf mit Nein stimmen. Die 10 nichtständigen Mitglieder können also gemeinsam eine Resolution verhindern, wenn mindestens 7 nicht zustimmen („sechstes Veto“)." },
  { id: "pwe-036", cat: "politik", topic: "Vereinte Nationen", type: "flashcard", emoji: "📣", level: 3,
    term: "Uniting for Peace (Resolution 377)",
    def: "Beschluss der Generalversammlung von 1950: Ist der Sicherheitsrat durch Veto blockiert, kann die GV in einer Notstandssondersitzung Empfehlungen zu Frieden und Sicherheit beschließen.",
    example: "Im März 2022 verurteilte die GV in einer solchen Sitzung die russische Invasion mit 141 Ja-Stimmen bei 5 Gegenstimmen." },
  { id: "pwe-037", cat: "politik", topic: "Vereinte Nationen", type: "quiz", emoji: "👔", level: 2,
    q: "Wer ist UN-Generalsekretär (Amtszeit bis Ende 2026)?",
    options: ["Ban Ki-moon", "António Guterres", "Kofi Annan", "Jens Stoltenberg"], answer: 1,
    explain: "Der Portugiese António Guterres amtiert seit 2017, seine zweite Amtszeit endet am 31.12.2026. Der Generalsekretär wird von der Generalversammlung auf Empfehlung des Sicherheitsrats gewählt – also ebenfalls mit Vetomöglichkeit der P5." },

  // ───────── USA ─────────
  { id: "pwe-038", cat: "politik", topic: "USA", type: "fact", emoji: "🇺🇸", level: 1,
    title: "Checks and Balances",
    text: "Präsident (Exekutive), Kongress aus Senat und Repräsentantenhaus (Legislative) und Supreme Court (Judikative) kontrollieren sich gegenseitig. Der Präsident kann Gesetze per Veto stoppen, der Kongress kann das mit 2/3-Mehrheit in beiden Kammern überstimmen.",
    more: "Anders als in Deutschland wird der Präsident nicht vom Parlament gewählt und kann nicht per Misstrauensvotum gestürzt werden – nur per **Impeachment**: Das Repräsentantenhaus klagt mit einfacher Mehrheit an, der Senat verurteilt mit 2/3. Verurteilt wurde noch nie ein Präsident." },
  { id: "pwe-039", cat: "politik", topic: "USA", type: "number", emoji: "🗳️", level: 1,
    value: "270", label: "Wahlleute-Stimmen für den Sieg (von 538)",
    text: "Der US-Präsident wird indirekt vom **Electoral College** gewählt. Jeder Bundesstaat hat so viele Wahlleute wie Abgeordnete plus 2 Senatoren; Washington D.C. hat 3.",
    more: "Fast alle Staaten vergeben ihre Wahlleute nach „Winner takes all“ – nur Maine und Nebraska teilen auf. Deshalb entscheiden wenige **Swing States** wie Pennsylvania, Georgia oder Wisconsin. Wahlkampf findet fast nur dort statt; in Kalifornien oder Texas steht das Ergebnis meist vorher fest." },
  { id: "pwe-040", cat: "politik", topic: "USA", type: "truefalse", emoji: "🧮", level: 1,
    q: "Wer landesweit die meisten Stimmen holt, wird automatisch US-Präsident.",
    answer: false,
    explain: "Falsch. 2000 (Bush gegen Gore) und 2016 (Trump gegen Clinton) gewann der Kandidat mit weniger Stimmen landesweit, aber mehr Wahlleuten. 2024 gewann Trump sowohl die Wahlleute als auch die Mehrheit der abgegebenen Stimmen (Popular Vote)." },
  { id: "pwe-041", cat: "politik", topic: "USA", type: "quiz", emoji: "🏛️", level: 2,
    q: "Was unterscheidet Senat und Repräsentantenhaus?",
    options: ["Der Senat wird alle 2 Jahre komplett neu gewählt", "Das Repräsentantenhaus bestätigt Bundesrichter", "Jeder Staat hat 2 Senatoren; das Haus hat 435 Sitze nach Bevölkerung", "Senatoren werden vom Präsidenten ernannt"], answer: 2,
    explain: "Senat: 100 Senatoren, 6 Jahre Amtszeit, alle 2 Jahre wird ein Drittel gewählt; bestätigt Richter und Minister, ratifiziert Verträge (2/3). Haus: 435 Abgeordnete, alle 2 Jahre gewählt, startet Haushaltsgesetze und Impeachments. Wyoming hat so viele Senatoren wie Kalifornien." },
  { id: "pwe-042", cat: "politik", topic: "USA", type: "fact", emoji: "👨‍⚖️", level: 2,
    title: "Supreme Court: 9 Richter auf Lebenszeit",
    text: "Der Präsident nominiert, der Senat bestätigt. Weil die Richter auf Lebenszeit ernannt sind, prägt jede Neubesetzung die Rechtsprechung für Jahrzehnte. Seit 2020 gibt es eine konservative Mehrheit von 6 zu 3.",
    more: "Drei der sechs Konservativen ernannte Trump in seiner ersten Amtszeit. Folgen: 2022 hob das Gericht Roe v. Wade auf – Abtreibungsrecht ist seither Sache der Bundesstaaten. 2024 sprach es Präsidenten weitgehende Immunität für Amtshandlungen zu. Darum sind Richterposten zentrale Wahlkampfthemen." },
  { id: "pwe-043", cat: "politik", topic: "USA", type: "flashcard", emoji: "🗣️", level: 3,
    term: "Filibuster",
    def: "Senatsregel: Eine Debatte kann nur mit 60 von 100 Stimmen beendet werden. Faktisch brauchen die meisten Gesetze im Senat daher 60 statt 51 Stimmen.",
    example: "Ausnahme „Budget Reconciliation“: Haushaltsgesetze wie Trumps „One Big Beautiful Bill“ (2025) passieren mit einfacher Mehrheit." },
  { id: "pwe-044", cat: "politik", topic: "USA", type: "event", emoji: "🦅", year: "2025", level: 1,
    title: "Trumps zweite Amtszeit beginnt",
    text: "Am 20. Januar 2025 wurde Donald Trump als 47. Präsident vereidigt – nach Grover Cleveland erst der zweite mit zwei nicht aufeinanderfolgenden Amtszeiten. Vizepräsident ist J. D. Vance.",
    more: "Prägend für den Start: eine Rekordzahl an Präsidialerlassen (Executive Orders), massive Zölle, harte Migrationspolitik, Kürzungen bei Behörden und Auslandshilfe (Auflösung von USAID) sowie der Austritt aus Pariser Abkommen und WHO. Der 22. Verfassungszusatz verbietet eine dritte Amtszeit." },
  { id: "pwe-045", cat: "politik", topic: "Zölle & Handel", type: "fact", emoji: "📦", level: 2,
    title: "„Liberation Day“: Zölle als Machtinstrument",
    text: "Am 2. April 2025 verkündete Trump „reziproke“ Zölle auf Importe aus fast allen Ländern, mit einem Basissatz von 10 % und Aufschlägen für Staaten mit Handelsüberschuss. Börsen brachen ein, viele Sätze wurden ausgesetzt und neu verhandelt.",
    more: "Trump stützte sich auf ein Notstandsgesetz (IEEPA), was Gerichte als Überdehnung prüften. Ziel laut Regierung: Reindustrialisierung und Abbau von Defiziten. Ökonomen betonen: Zölle zahlt zunächst der Importeur – die Kosten landen oft bei US-Firmen und Konsumenten." },
  { id: "pwe-046", cat: "politik", topic: "Zölle & Handel", type: "whatif", emoji: "🧾", level: 2,
    q: "Was passiert, wenn die USA hohe Zölle auf Importe erheben?",
    steps: ["US-Importeur zahlt den Zoll an den Staat", "Höhere Preise für Firmen und Konsumenten", "Handelspartner drohen mit Gegenzöllen", "Lieferketten werden umgebaut", "Weniger Welthandel, mehr Unsicherheit"],
    text: "Zölle sind eine Steuer auf Importe. Exporteure tragen sie nur teilweise, etwa über Preisnachlässe. Gewinner können geschützte heimische Branchen sein; Verlierer sind Branchen mit importierten Vorprodukten und Exporteure, die Gegenzöllen ausgesetzt sind." },
  { id: "pwe-047", cat: "politik", topic: "Zölle & Handel", type: "quiz", emoji: "🤝", level: 3,
    q: "Welchen Zollsatz vereinbarten EU und USA im Sommer 2025 grundsätzlich für die meisten EU-Exporte?",
    options: ["0 %", "15 %", "25 %", "50 %"], answer: 1,
    explain: "Im Juli 2025 einigten sich Trump und von der Leyen auf eine Obergrenze von 15 % für die meisten EU-Waren (u. a. Autos), um höhere angedrohte Sätze abzuwenden. Kritiker sahen ein asymmetrisches Ergebnis, Befürworter vermiedene Eskalation. Für Stahl und Aluminium galten Sonderregeln." },
  { id: "pwe-048", cat: "politik", topic: "USA", type: "truefalse", emoji: "📅", level: 2,
    q: "Bei den US-Zwischenwahlen (Midterms) wird auch der Präsident neu gewählt.",
    answer: false,
    explain: "Falsch. Die Midterms liegen zwei Jahre nach der Präsidentschaftswahl. Gewählt werden das ganze Repräsentantenhaus und ein Drittel des Senats. Traditionell verliert die Partei des Präsidenten dabei Sitze – die nächsten Midterms sind im November 2026." },
  { id: "pwe-049", cat: "politik", topic: "USA", type: "quiz", emoji: "📝", level: 1,
    q: "Was ist eine Executive Order?",
    options: ["Ein Gesetz des Kongresses", "Ein Urteil des Supreme Court", "Eine Weisung des Präsidenten an die Bundesverwaltung", "Ein Volksentscheid"], answer: 2,
    explain: "Executive Orders steuern die Verwaltung ohne Kongress – schnell, aber begrenzt: Sie dürfen Gesetzen und Verfassung nicht widersprechen, Gerichte können sie stoppen, und der nächste Präsident kann sie per Federstrich aufheben." },
  { id: "pwe-050", cat: "politik", topic: "USA", type: "flashcard", emoji: "🌐", level: 2,
    term: "America First",
    def: "Außenpolitische Leitlinie Trumps: nationale Interessen vor multilateralen Verpflichtungen, Skepsis gegenüber Bündnissen und Freihandel, Deals statt Regeln.",
    example: "Austritte aus Pariser Abkommen, WHO und UNESCO, Zölle auch gegen Verbündete, Forderung nach 5 % Verteidigungsausgaben in der NATO." },

  // ───────── China ─────────
  { id: "pwe-140", cat: "politik", topic: "USA", type: "order", emoji: "📜", level: 2,
    q: "Wie wird ein Gesetz in den USA verabschiedet? Bringe die Schritte in die Reihenfolge.",
    items: ["Einbringung im Kongress und Beratung im Ausschuss", "Beschluss in Repräsentantenhaus und Senat (gleicher Text)", "Präsident unterschreibt oder legt Veto ein", "Bei Veto: Kongress kann mit 2/3 überstimmen"],
    explain: "Beide Kammern müssen exakt denselben Text beschließen – Unterschiede werden in einem Vermittlungsausschuss oder per Ping-Pong bereinigt. Weil Mehrheiten oft knapp sind, scheitern viele Vorhaben am Kongress; Präsidenten weichen dann auf Executive Orders aus." },
  { id: "pwe-051", cat: "politik", topic: "China", type: "fact", emoji: "🇨🇳", level: 1,
    title: "Die Partei steht über dem Staat",
    text: "In China führt die Kommunistische Partei (KPCh, ca. 100 Mio. Mitglieder) Staat, Armee und Justiz. Das eigentliche Machtzentrum ist der 7-köpfige Ständige Ausschuss des Politbüros – an der Spitze Generalsekretär **Xi Jinping**.",
    more: "Die Volksbefreiungsarmee ist formal eine Parteiarmee, keine Staatsarmee. Xis wichtigstes Amt ist das des Generalsekretärs (seit 2012), nicht das des Staatspräsidenten (seit 2013). Gewaltenteilung lehnt die KPCh ausdrücklich als „westliches Konzept“ ab." },
  { id: "pwe-052", cat: "politik", topic: "China", type: "event", emoji: "♾️", year: "2018", level: 2,
    title: "Amtszeitbegrenzung abgeschafft",
    text: "Der Volkskongress strich 2018 die Begrenzung auf zwei Amtszeiten für den Staatspräsidenten. 2022 ließ sich Xi Jinping als erster seit Mao eine dritte Amtszeit als Parteichef geben.",
    more: "Nach Maos Kulturrevolution hatte Deng Xiaoping kollektive Führung und geordnete Machtwechsel eingeführt, um Personenkult zu verhindern. Xi hat diese Regeln zurückgedreht – mit Machtkonzentration, aber auch dem Risiko, dass es keine geregelte Nachfolge gibt." },
  { id: "pwe-053", cat: "politik", topic: "Taiwan", type: "fact", emoji: "🇹🇼", level: 1,
    title: "Die Taiwan-Frage in 30 Sekunden",
    text: "1949 floh die unterlegene Kuomintang-Regierung nach Taiwan. Peking sieht Taiwan als abtrünnige Provinz und schließt Gewalt zur „Wiedervereinigung“ nicht aus. Taiwan ist heute eine Demokratie mit eigener Regierung, Armee und Währung.",
    more: "Nur rund ein Dutzend Staaten erkennen Taiwan diplomatisch an. Die meisten, auch die USA und Deutschland, verfolgen eine **Ein-China-Politik**: offizielle Beziehungen nur zu Peking, aber enge inoffizielle Kontakte zu Taipeh. Die Mehrheit der Taiwaner will den Status quo erhalten." },
  { id: "pwe-054", cat: "politik", topic: "Taiwan", type: "whatif", emoji: "🚢", level: 2,
    q: "Was passiert, wenn China Taiwan blockiert?",
    steps: ["Schiffs- und Flugverkehr nach Taiwan stockt", "Chiplieferungen von TSMC brechen ein", "Weltweit Produktionsstopps (Autos, Handys)", "Sanktionen gegen China, Börsenschock", "Risiko militärischer Eskalation mit USA"],
    text: "Taiwan fertigt die meisten Spitzenchips. Eine Blockade wäre ein globaler Wirtschaftsschock; Schätzungen (z. B. Bloomberg Economics) liegen bei mehreren Prozent des Welt-BIP. Blockade-Manöver übt China regelmäßig." },
  { id: "pwe-055", cat: "politik", topic: "Taiwan", type: "flashcard", emoji: "🌫️", level: 3,
    term: "Strategische Ambiguität",
    def: "US-Politik gegenüber Taiwan: Washington lässt offen, ob es Taiwan bei einem Angriff militärisch verteidigen würde. Das soll China abschrecken und Taiwan zugleich von einer formellen Unabhängigkeitserklärung abhalten.",
    example: "Grundlage ist der Taiwan Relations Act (1979): Die USA liefern Taiwan Waffen zur Selbstverteidigung, ohne eine Beistandspflicht." },
  { id: "pwe-056", cat: "politik", topic: "China", type: "quiz", emoji: "🛤️", level: 1,
    q: "Was ist die „Neue Seidenstraße“ (Belt and Road Initiative)?",
    options: ["Ein Freihandelsabkommen zwischen China und der EU", "Ein Militärbündnis Chinas mit Russland", "Ein Hochgeschwindigkeitszug von Peking nach Berlin", "Chinas globales Infrastruktur- und Investitionsprogramm seit 2013"], answer: 3,
    explain: "Xi startete die BRI 2013: Häfen, Bahnen, Kraftwerke in über 140 Ländern, finanziert vor allem durch chinesische Kredite. Kritik: Schuldenabhängigkeit (Beispiel Sri Lanka, Hafen Hambantota) und geopolitischer Einfluss. Italien stieg 2023 als einziges G7-Land wieder aus." },
  { id: "pwe-057", cat: "politik", topic: "China", type: "flashcard", emoji: "🔺", level: 2,
    term: "Partner – Wettbewerber – Systemrivale",
    def: "Dreiklang der EU-China-Strategie seit 2019: Partner bei globalen Themen wie Klima, wirtschaftlicher Wettbewerber und systemischer Rivale bei Werten und Regierungsmodell.",
    example: "Die EU kooperiert bei Klimazielen, erhebt aber Ausgleichszölle auf chinesische E-Autos (2024) wegen Subventionen." },
  { id: "pwe-058", cat: "politik", topic: "China", type: "truefalse", emoji: "👥", level: 1,
    q: "China ist das bevölkerungsreichste Land der Welt.",
    answer: false,
    explain: "Falsch – seit 2023. Laut UN hat Indien China überholt; beide haben über 1,4 Mrd. Einwohner. Chinas Bevölkerung schrumpft seit 2022 und altert schnell, eine Spätfolge der Ein-Kind-Politik (1980–2015). Das belastet Wachstum und Sozialsysteme." },
  { id: "pwe-059", cat: "politik", topic: "China", type: "quiz", emoji: "🧭", level: 3,
    q: "Was meint „De-Risking“ im Umgang mit China?",
    options: ["Abhängigkeiten in kritischen Bereichen gezielt verringern, Handel sonst fortsetzen", "Kompletter wirtschaftlicher Bruch mit China", "Höhere Zinsen für chinesische Anleihen", "Verbot aller chinesischen Investitionen"], answer: 0,
    explain: "De-Risking (Begriff von von der Leyen 2023) grenzt sich vom **Decoupling** (Entkopplung) ab: Diversifizieren bei Rohstoffen, Chips, Arzneimitteln, Batterien – aber kein Abbruch der Handelsbeziehungen. China ist einer der größten Handelspartner Deutschlands." },

  // ───────── Russland & Ukraine ─────────
  { id: "pwe-060", cat: "politik", topic: "Ukraine-Krieg", type: "order", emoji: "🗓️", level: 1,
    q: "Bringe die Eskalationsstufen des russisch-ukrainischen Konflikts in die richtige Reihenfolge.",
    items: ["Budapester Memorandum: Ukraine gibt Atomwaffen ab", "Maidan-Proteste und Annexion der Krim", "Russische Großinvasion", "Russland erklärt vier Regionen für annektiert"],
    explain: "1994 Budapester Memorandum, 2013/14 Maidan und Krim-Annexion (März 2014) sowie Krieg im Donbas, 24. Februar 2022 Großinvasion, September 2022 Scheinannexion von Donezk, Luhansk, Saporischschja und Cherson – keine davon kontrolliert Russland vollständig." },
  { id: "pwe-061", cat: "politik", topic: "Ukraine-Krieg", type: "event", emoji: "🏝️", year: "2014", level: 1,
    title: "Annexion der Krim",
    text: "Nach dem Sturz des prorussischen Präsidenten Janukowytsch besetzten russische Soldaten ohne Hoheitsabzeichen die Krim. Nach einem international nicht anerkannten „Referendum“ annektierte Russland die Halbinsel im März 2014.",
    more: "Es war die erste gewaltsame Grenzverschiebung in Europa seit 1945. Der Westen reagierte mit vergleichsweise milden Sanktionen; Deutschland baute danach sogar Nord Stream 2. Viele Analysten sehen darin rückblickend ein Signal an Moskau, dass Aggression bezahlbar sei." },
  { id: "pwe-062", cat: "politik", topic: "Ukraine-Krieg", type: "event", emoji: "💥", year: "2022", level: 1,
    title: "Russlands Großinvasion der Ukraine",
    text: "Am 24. Februar 2022 griff Russland die Ukraine von Norden, Osten und Süden an. Der Plan, Kiew in wenigen Tagen einzunehmen, scheiterte; der Krieg wurde zum größten in Europa seit 1945.",
    more: "Folgen in Kürze: Millionen Flüchtlinge, Energiekrise in Europa, „Zeitenwende“ in Deutschland (100-Mrd.-Sondervermögen), NATO-Beitritte Finnlands und Schwedens, EU-Kandidatenstatus der Ukraine. Hunderttausende Soldaten wurden getötet oder verwundet." },
  { id: "pwe-063", cat: "politik", topic: "Ukraine-Krieg", type: "truefalse", emoji: "☢️", level: 2,
    q: "Die Ukraine besaß nach dem Ende der Sowjetunion eines der größten Atomwaffenarsenale der Welt.",
    answer: true,
    explain: "Wahr. Rund 1.900 strategische Sprengköpfe lagen 1991 auf ukrainischem Boden. Im **Budapester Memorandum** (1994) gab die Ukraine sie ab; Russland, USA und Großbritannien sicherten ihre territoriale Integrität zu. Russlands Angriff gilt daher als schwerer Schlag für die Nichtverbreitung." },
  { id: "pwe-064", cat: "politik", topic: "Sanktionen", type: "fact", emoji: "🚫", level: 2,
    title: "Wie Sanktionen gegen Russland wirken sollen",
    text: "Die wichtigsten Hebel: rund 300 Mrd. US-Dollar Zentralbankreserven eingefroren, große Banken vom SWIFT-System getrennt, Exportverbote für Hochtechnologie, Ölembargo der EU und ein Preisdeckel für russisches Öl.",
    more: "Das Ziel ist weniger ein schneller Kollaps als die schrittweise Schwächung der Kriegsfinanzierung. Schwachstellen: Umgehung über Drittstaaten (Türkei, Zentralasien, Kaukasus) und die „Schattenflotte“ alter Tanker. Russland lenkte seine Ölexporte stark nach China und Indien um." },
  { id: "pwe-065", cat: "politik", topic: "Sanktionen", type: "flashcard", emoji: "🛢️", level: 3,
    term: "Ölpreisdeckel",
    def: "Seit Dezember 2022 dürfen westliche Reedereien und Versicherer russisches Öl nur transportieren bzw. versichern, wenn es unter einem Höchstpreis verkauft wird (anfangs 60 US-$ je Barrel; EU senkte ihn 2025).",
    example: "Idee: Öl soll weiter fließen (stabile Weltpreise), Russland aber weniger daran verdienen. Umgehung: Schattenflotte ohne westliche Versicherung." },
  { id: "pwe-066", cat: "politik", topic: "Sanktionen", type: "whatif", emoji: "🔐", level: 3,
    q: "Was passiert, wenn der Westen die Zentralbankreserven eines Landes einfriert?",
    steps: ["Land kann Reserven nicht für Stützung nutzen", "Währung gerät unter Druck", "Andere Staaten fürchten ähnliche Schritte", "Mehr Gold- und Yuan-Reserven weltweit", "Streit: Erträge für die Ukraine nutzen?"],
    text: "Das Einfrieren russischer Reserven 2022 war ein Novum gegen eine G20-Macht. Die EU nutzt die Zinserträge (Windfall Profits) für die Ukraine. Eine Beschlagnahme des Kapitals selbst ist rechtlich und finanzpolitisch umstritten – man fürchtet um das Vertrauen in den Euro." },
  { id: "pwe-067", cat: "politik", topic: "Energie", type: "number", emoji: "🔥", level: 1,
    value: "55 %", label: "Anteil Russlands an Deutschlands Gasimporten 2021",
    text: "Vor dem Krieg kam mehr als die Hälfte des in Deutschland genutzten Erdgases aus Russland. Ab Herbst 2022 floss praktisch kein russisches Pipelinegas mehr nach Deutschland.",
    more: "Ersatz: LNG-Terminals an der Küste (das erste in Wilhelmshaven, gebaut in unter einem Jahr), mehr Gas aus Norwegen, Niederlande, Belgien sowie Einsparungen. Folge: Gas- und Strompreisschock 2022, Inflation zeitweise fast 9 %. Lehre: Energieabhängigkeit ist ein sicherheitspolitisches Risiko." },
  { id: "pwe-068", cat: "politik", topic: "Energie", type: "quiz", emoji: "🌊", level: 1,
    q: "Was geschah im September 2022 mit den Nord-Stream-Pipelines?",
    options: ["Sie wurden durch Explosionen in der Ostsee schwer beschädigt", "Sie wurden von Deutschland verstaatlicht", "Sie wurden an China verkauft", "Sie wurden für Wasserstoff umgerüstet"], answer: 0,
    explain: "Am 26. September 2022 zerstörten Sprengungen drei der vier Röhren von Nord Stream 1 und 2 nahe Bornholm. Die Ermittlungen deutscher Behörden führten zu ukrainischen Verdächtigen; die Aufklärung ist politisch heikel. Der Vorfall zeigte die Verwundbarkeit kritischer Infrastruktur." },
  { id: "pwe-069", cat: "politik", topic: "Ukraine-Krieg", type: "number", emoji: "🗺️", level: 2,
    value: "≈ 20 %", label: "der Ukraine unter russischer Kontrolle (Stand 2025)",
    text: "Inklusive Krim und Teilen des Donbas kontrolliert Russland rund ein Fünftel der Ukraine (Stand 2025). Der Frontverlauf bewegte sich seit Ende 2022 nur noch langsam.",
    more: "Der Krieg wurde zum Abnutzungskrieg: Drohnen dominieren das Gefechtsfeld, Durchbrüche sind teuer. Entscheidend werden daher Munition, Personal und Industriekapazität – und westliche Unterstützung. Verhandlungen kreisen um Gebietsfragen und Sicherheitsgarantien für die Ukraine." },
  { id: "pwe-070", cat: "politik", topic: "Ukraine-Krieg", type: "quiz", emoji: "🛰️", level: 3,
    q: "Warum lehnt Russland einen NATO-Beitritt der Ukraine so vehement ab – aus Sicht der Realismus-Theorie?",
    options: ["Wegen religiöser Unterschiede", "Weil die Ukraine kein Gas liefert", "Weil Großmächte Pufferzonen an ihren Grenzen beanspruchen", "Weil die NATO-Charta Russland verbietet"], answer: 2,
    explain: "Realisten wie John Mearsheimer argumentieren mit Einflusssphären und Sicherheitsdilemma. Kritiker halten dagegen: Souveräne Staaten wählen ihre Bündnisse frei (KSZE-Schlussakte, Charta von Paris), und Russlands imperialer Anspruch erkläre den Krieg besser. Beide Sichtweisen sollte man kennen." },

  // ───────── Nahost ─────────
  { id: "pwe-071", cat: "politik", topic: "Nahost", type: "order", emoji: "🕰️", level: 2,
    q: "Bringe die Schlüsselereignisse des Nahostkonflikts in die richtige Reihenfolge.",
    items: ["Staatsgründung Israels", "Sechstagekrieg", "Oslo-Abkommen", "Hamas übernimmt Gaza", "Hamas-Massaker vom 7. Oktober"],
    explain: "1948 Gründung und erster Krieg (für Palästinenser die „Nakba“), 1967 Sechstagekrieg mit Besetzung von Westjordanland, Gaza, Ostjerusalem und Golan, 1993 Oslo (gegenseitige Anerkennung Israel/PLO), 2007 Hamas-Machtübernahme in Gaza, 2023 der 7. Oktober." },
  { id: "pwe-072", cat: "politik", topic: "Nahost", type: "event", emoji: "🕯️", year: "2023", level: 1,
    title: "Der 7. Oktober",
    text: "Terroristen der Hamas und anderer Gruppen drangen am 7. Oktober 2023 aus Gaza nach Israel ein, töteten rund 1.200 Menschen, überwiegend Zivilisten, und verschleppten etwa 250 Geiseln. Es war der tödlichste Tag für Juden seit dem Holocaust.",
    more: "Israel reagierte mit einem Krieg gegen die Hamas in Gaza. Der Angriff fiel in eine Phase, in der eine israelisch-saudische Annäherung im Raum stand – viele Analysten sehen in deren Torpedierung ein Motiv. Der Konflikt weitete sich auf Libanon (Hisbollah), Jemen (Huthis) und Iran aus." },
  { id: "pwe-073", cat: "politik", topic: "Nahost", type: "fact", emoji: "🏚️", level: 1,
    title: "Gaza-Krieg: humanitäre Katastrophe",
    text: "Nach Angaben der von der Hamas geführten Gesundheitsbehörde wurden bis Oktober 2025 über 67.000 Menschen in Gaza getötet; der Großteil der rund 2,1 Mio. Bewohner wurde vertrieben, weite Teile des Gebiets sind zerstört.",
    more: "Die Opferzahlen unterscheiden nicht zwischen Kämpfern und Zivilisten; UN und viele Forscher halten sie aber für grob belastbar. Im August 2025 stellte das UN-gestützte IPC-System eine Hungersnot im Raum Gaza-Stadt fest. Im Oktober 2025 trat eine Waffenruhe auf Basis eines US-Plans in Kraft, die lebenden Geiseln kamen frei." },
  { id: "pwe-074", cat: "politik", topic: "Nahost", type: "flashcard", emoji: "✌️", level: 1,
    term: "Zweistaatenlösung",
    def: "Friedensmodell: ein unabhängiger palästinensischer Staat (Westjordanland, Gaza, Hauptstadt Ostjerusalem) neben Israel, mit gegenseitiger Anerkennung und Sicherheitsgarantien.",
    example: "Offizielle Linie von UN, EU und Deutschland. Hürden: israelische Siedlungen im Westjordanland, Hamas, Jerusalem-Frage, Flüchtlinge, tiefes Misstrauen auf beiden Seiten." },
  { id: "pwe-075", cat: "politik", topic: "Nahost", type: "quiz", emoji: "🕊️", level: 2,
    q: "Welche Staaten normalisierten 2020 mit den Abraham-Abkommen ihre Beziehungen zu Israel zuerst?",
    options: ["Saudi-Arabien und Katar", "Ägypten und Jordanien", "Iran und Irak", "Vereinigte Arabische Emirate und Bahrain"], answer: 3,
    explain: "VAE und Bahrain unterzeichneten im September 2020 unter US-Vermittlung, Marokko und Sudan folgten. Ägypten (1979) und Jordanien (1994) hatten schon früher Frieden geschlossen. Das große Ziel – Saudi-Arabien – steht noch aus; Riad knüpft es an einen Weg zu einem Palästinenserstaat." },
  { id: "pwe-076", cat: "politik", topic: "Iran", type: "fact", emoji: "⚛️", level: 2,
    title: "Atomabkommen mit Iran: Aufstieg und Fall",
    text: "2015 vereinbarten Iran, die P5 und Deutschland (JCPOA): Begrenzung der Urananreicherung gegen Aufhebung von Sanktionen. 2018 stiegen die USA unter Trump aus, Iran reicherte danach bis auf 60 % an – nah an waffenfähigen 90 %.",
    more: "Im Juni 2025 griff Israel iranische Atom- und Militäranlagen an („Zwölftagekrieg“); die USA bombardierten die Anlagen Fordo, Natanz und Isfahan. Im September 2025 lösten Frankreich, Großbritannien und Deutschland den „Snapback“ aus: Die UN-Sanktionen gegen Iran traten wieder in Kraft." },
  { id: "pwe-077", cat: "politik", topic: "Iran", type: "whatif", emoji: "🛳️", level: 2,
    q: "Was passiert, wenn Iran die Straße von Hormus sperrt?",
    steps: ["Rund 1/5 des weltweiten Ölhandels stockt", "Ölpreis schießt nach oben", "Auch LNG aus Katar fällt aus", "Inflation und Rezessionsgefahr weltweit", "US-Marine greift wahrscheinlich ein"],
    text: "Die Meerenge zwischen Iran und Oman ist an der engsten Stelle nur rund 33 km breit. Umgehungspipelines Saudi-Arabiens und der VAE reichen nicht für alle Mengen. Asiatische Importeure wie China, Indien, Japan und Südkorea wären stark betroffen." },
  { id: "pwe-078", cat: "politik", topic: "Iran", type: "flashcard", emoji: "🕸️", level: 2,
    term: "„Achse des Widerstands“",
    def: "Von Iran unterstütztes Netzwerk nichtstaatlicher und staatlicher Akteure gegen Israel und die USA: Hisbollah (Libanon), Hamas, Huthis (Jemen), Milizen im Irak, bis Ende 2024 auch das Assad-Regime in Syrien.",
    example: "Seit 2023 stark geschwächt: Hisbollah-Führung getötet, Assad im Dezember 2024 gestürzt, Hamas militärisch dezimiert." },
  { id: "pwe-079", cat: "politik", topic: "Nahost", type: "whatif", emoji: "🚢", level: 2,
    q: "Was passiert, wenn die Huthis Handelsschiffe im Roten Meer angreifen?",
    steps: ["Reedereien meiden den Suezkanal", "Umweg ums Kap der Guten Hoffnung", "Rund 10–14 Tage längere Fahrt Asien–Europa", "Frachtraten und Versicherungen steigen", "Ägypten verliert Kanaleinnahmen"],
    text: "Ab Ende 2023 griffen die Huthis aus Solidarität mit der Hamas Schiffe an. Der Suez-Verkehr brach um mehr als die Hälfte ein. Ein Lehrbuchfall, wie eine kleine Miliz durch Nadelöhre globaler Lieferketten große wirtschaftliche Wirkung erzielt." },
  { id: "pwe-080", cat: "politik", topic: "Golfstaaten", type: "quiz", emoji: "🛢️", level: 2,
    q: "Welches Land vermittelte 2023 die Wiederaufnahme diplomatischer Beziehungen zwischen Saudi-Arabien und Iran?",
    options: ["China", "USA", "Russland", "Türkei"], answer: 0,
    explain: "Die Einigung im März 2023 in Peking war ein diplomatischer Prestigeerfolg Chinas in einer Region, die lange als US-Domäne galt. Hintergrund: Saudi-Arabien will Ruhe für seine Wirtschaftsreform „Vision 2030“; China ist größter Abnehmer von Golf-Öl." },
  { id: "pwe-081", cat: "politik", topic: "Golfstaaten", type: "fact", emoji: "🏙️", level: 2,
    title: "Golfstaaten: Vom Ölexporteur zur Mittelmacht",
    text: "Saudi-Arabien, VAE und Katar nutzen ihre Öl- und Gasmilliarden für Staatsfonds, Diversifizierung und Diplomatie. Sie verhandeln mit allen Seiten – USA, China, Russland – und vermitteln selbst in Konflikten.",
    more: "Beispiele: Katar vermittelte zwischen Israel und Hamas sowie mit den Taliban, Saudi-Arabien war Gastgeber von US-Russland- und US-Ukraine-Gesprächen 2025, die VAE vermitteln Gefangenenaustausche. Staatsfonds wie Saudi-Arabiens PIF oder Abu Dhabis ADIA gehören zu den größten Investoren der Welt." },
  { id: "pwe-082", cat: "politik", topic: "Nahost", type: "truefalse", emoji: "📜", level: 3,
    q: "Mehrere westliche Staaten, darunter Frankreich und Großbritannien, haben 2025 Palästina als Staat anerkannt.",
    answer: true,
    explain: "Wahr. Im September 2025 erkannten u. a. Frankreich, Großbritannien, Kanada, Australien und Portugal Palästina an – insgesamt tun das damit über drei Viertel der UN-Mitglieder. Deutschland und die USA lehnen eine Anerkennung zum jetzigen Zeitpunkt ab und sehen sie als Ergebnis von Verhandlungen." },

  // ───────── Indien & Globaler Süden ─────────
  { id: "pwe-083", cat: "politik", topic: "Indien", type: "fact", emoji: "🇮🇳", level: 1,
    title: "Indien: größte Demokratie der Welt",
    text: "Mit über 1,4 Mrd. Einwohnern ist Indien seit 2023 das bevölkerungsreichste Land. Bei der Wahl 2024 waren rund 970 Mio. Menschen wahlberechtigt. Premierminister ist seit 2014 Narendra Modi (BJP).",
    more: "Indien ist eine der am schnellsten wachsenden großen Volkswirtschaften und rückt laut IWF-Prognosen 2025 auf Platz 4 der Welt vor (nominal, vor Japan). Außenpolitisch setzt es auf **strategische Autonomie**: Partner der USA im Quad, aber zugleich Käufer russischen Öls und Waffen und Mitglied der BRICS." },
  { id: "pwe-084", cat: "politik", topic: "Indien", type: "flashcard", emoji: "🔷", level: 2,
    term: "Quad",
    def: "Quadrilateraler Sicherheitsdialog von USA, Japan, Indien und Australien. Lockere Kooperation (kein Bündnis) für einen „freien und offenen Indopazifik“ – faktisch ein Gegengewicht zu China.",
    example: "Themen: Seesicherheit, Lieferketten, Impfstoffe, kritische Technologien, Katastrophenhilfe." },
  { id: "pwe-085", cat: "politik", topic: "BRICS", type: "quiz", emoji: "🧱", level: 1,
    q: "Wofür stehen die Buchstaben der ursprünglichen BRICS?",
    options: ["Brasilien, Russland, Indien, China, Südafrika", "Belgien, Rumänien, Island, China, Spanien", "Brasilien, Russland, Iran, China, Saudi-Arabien", "Bolivien, Russland, Indonesien, Chile, Südafrika"], answer: 0,
    explain: "Den Begriff „BRIC“ prägte 2001 Goldman-Sachs-Ökonom Jim O’Neill für aufstrebende Volkswirtschaften. 2009 wurde daraus ein Gipfelformat, 2010/11 kam Südafrika dazu. Seit 2024 traten u. a. Ägypten, Äthiopien, Iran, die VAE und 2025 Indonesien bei." },
  { id: "pwe-086", cat: "politik", topic: "BRICS", type: "truefalse", emoji: "🪙", level: 1,
    q: "Die BRICS-Staaten haben eine gemeinsame Währung eingeführt.",
    answer: false,
    explain: "Falsch. Es gibt Debatten über Handel in Landeswährungen und eigene Zahlungssysteme, um den Dollar zu umgehen, aber keine gemeinsame Währung. Hindernis: Die Mitglieder sind sehr unterschiedlich und teils Rivalen – vor allem Indien und China. Konkretes Projekt ist die New Development Bank (Shanghai)." },
  { id: "pwe-087", cat: "politik", topic: "Globaler Süden", type: "flashcard", emoji: "🌎", level: 1,
    term: "Globaler Süden",
    def: "Sammelbegriff für Länder Afrikas, Lateinamerikas und große Teile Asiens – weniger geografisch als politisch gemeint: ehemals kolonisiert, oft Schwellen- oder Entwicklungsländer, mit Wunsch nach mehr Mitsprache.",
    example: "Viele Staaten des Globalen Südens verurteilten Russlands Invasion in der UN, beteiligten sich aber nicht an Sanktionen." },
  { id: "pwe-088", cat: "politik", topic: "Globaler Süden", type: "number", emoji: "🌍", level: 2,
    value: "G21", label: "Seit 2023 sitzt die Afrikanische Union mit am G20-Tisch",
    text: "Auf Indiens G20-Gipfel in Neu-Delhi wurde die Afrikanische Union (55 Staaten) ständiges Mitglied – gleichrangig mit der EU.",
    more: "Ein Symbol für die Verschiebung der Gewichte: Indien positionierte sich als „Stimme des Globalen Südens“. Der Name „G20“ blieb trotzdem. 2025 hatte Südafrika als erstes afrikanisches Land die G20-Präsidentschaft; die USA boykottierten den Gipfel in Johannesburg." },

  // ───────── Klimapolitik ─────────
  { id: "pwe-089", cat: "politik", topic: "Klimapolitik", type: "fact", emoji: "🌡️", level: 1,
    title: "Pariser Abkommen: deutlich unter 2 Grad",
    text: "2015 auf der COP21 beschlossen: Die Erderwärmung soll auf **deutlich unter 2 °C** begrenzt werden, mit Anstrengungen für **1,5 °C** gegenüber vorindustriellem Niveau. Fast alle Staaten sind dabei.",
    more: "Der Trick des Abkommens: Statt verbindlicher Quoten (wie im Kyoto-Protokoll 1997) legt jedes Land eigene Ziele fest (**NDCs**) und muss sie alle 5 Jahre verschärfen. Vorteil: breite Teilnahme. Nachteil: keine Sanktionen – die Summe der Zusagen reicht bislang nicht für 1,5 °C." },
  { id: "pwe-090", cat: "politik", topic: "Klimapolitik", type: "number", emoji: "🔥", level: 2,
    value: "≈ 1,55 °C", label: "Globale Erwärmung 2024 – erstes Jahr über 1,5 Grad",
    text: "Laut Weltwetterorganisation (WMO) lag 2024 rund 1,55 °C über dem vorindustriellen Niveau – das wärmste Jahr seit Beginn der Messungen.",
    more: "Wichtig: Das 1,5-Grad-Ziel bezieht sich auf den Durchschnitt über rund 20 Jahre, nicht auf ein Einzeljahr. Paris ist damit formal nicht verfehlt. Aber der Trend zeigt: Ohne drastische Emissionssenkungen wird die Schwelle in den 2030er-Jahren dauerhaft überschritten." },
  { id: "pwe-091", cat: "politik", topic: "Klimapolitik", type: "quiz", emoji: "🏭", level: 1,
    q: "Welches Land stößt aktuell die meisten Treibhausgase aus?",
    options: ["USA", "Indien", "China", "Russland"], answer: 2,
    explain: "China verursacht rund 30 % der globalen CO₂-Emissionen, mehr als USA und EU zusammen. Historisch (kumuliert seit 1850) liegen jedoch die USA vorn, und pro Kopf stoßen US-Amerikaner deutlich mehr aus. Gleichzeitig baut China weltweit am meisten Solar- und Windkraft zu." },
  { id: "pwe-092", cat: "politik", topic: "Klimapolitik", type: "flashcard", emoji: "🌴", level: 1,
    term: "COP",
    def: "„Conference of the Parties“: jährliche UN-Weltklimakonferenz der Vertragsstaaten der Klimarahmenkonvention (1992). Beschlüsse fallen im Konsens.",
    example: "COP21 Paris 2015 (Pariser Abkommen), COP28 Dubai 2023 (erstmals Abkehr von fossilen Brennstoffen im Text), COP30 Belém (Brasilien) 2025." },
  { id: "pwe-093", cat: "politik", topic: "Klimapolitik", type: "truefalse", emoji: "🚪", level: 1,
    q: "Die USA sind unter Trump zweimal aus dem Pariser Abkommen ausgetreten.",
    answer: true,
    explain: "Wahr. Erster Austritt 2017 angekündigt, wirksam Ende 2020 – Biden trat 2021 wieder bei. Am ersten Tag der zweiten Amtszeit (Januar 2025) erklärte Trump erneut den Austritt, wirksam nach einem Jahr. Die USA sind der zweitgrößte Emittent der Welt." },
  { id: "pwe-094", cat: "politik", topic: "Klimapolitik", type: "whatif", emoji: "🧱", level: 3,
    q: "Was passiert, wenn die EU einen CO₂-Grenzausgleich (CBAM) erhebt?",
    steps: ["Stahl- und Zementimporte zahlen CO₂-Preis", "Preisnachteil durch EU-Emissionshandel sinkt", "Weniger Abwanderung („Carbon Leakage“)", "Exporteure wie China, Indien protestieren", "Anreiz für eigene CO₂-Preise im Ausland"],
    text: "CBAM gleicht aus, dass EU-Firmen für CO₂ zahlen, Konkurrenten im Ausland oft nicht. Die Berichtsphase startete 2023, die kostenpflichtige Phase beginnt 2026. Kritiker im Globalen Süden sehen darin verdeckten Protektionismus." },
  { id: "pwe-095", cat: "politik", topic: "Klimapolitik", type: "number", emoji: "💵", level: 3,
    value: "300 Mrd. $", label: "Jährliche Klimafinanzierung für Entwicklungsländer bis 2035",
    text: "Auf der COP29 in Baku (2024) vereinbart: Industriestaaten sollen ab 2035 mindestens 300 Mrd. US-Dollar pro Jahr mobilisieren. Das alte Ziel lag bei 100 Mrd.",
    more: "Entwicklungsländer hatten über 1 Billion gefordert und kritisierten das Ergebnis scharf. Dahinter steht die Gerechtigkeitsfrage: Wer historisch viel emittiert hat, soll die Anpassung armer, oft stark betroffener Länder mitfinanzieren. Streitpunkt bleibt, ob auch China und Golfstaaten zahlen sollen." },

  { id: "pwe-141", cat: "politik", topic: "Klimapolitik", type: "order", emoji: "🌱", level: 1,
    q: "Bringe die Meilensteine der globalen Klimapolitik in die richtige Reihenfolge.",
    items: ["Klimarahmenkonvention in Rio", "Kyoto-Protokoll", "Pariser Abkommen", "COP28 Dubai: Abkehr von Fossilen"],
    explain: "1992 Rio (Grundlage aller COPs), 1997 Kyoto (feste Ziele nur für Industrieländer, USA nie ratifiziert), 2015 Paris (Ziele für alle, aber selbst gesetzt), 2023 Dubai (erstmals Aufruf zur Abkehr von fossilen Brennstoffen)." },

  // ───────── Welthandel & WTO ─────────
  { id: "pwe-096", cat: "politik", topic: "Welthandel", type: "fact", emoji: "🌐", level: 1,
    title: "WTO: Regeln für den Welthandel",
    text: "Die Welthandelsorganisation (1995, Genf) ist Nachfolgerin des GATT von 1947. Rund 166 Mitglieder decken fast den gesamten Welthandel ab. Kernprinzip: **Meistbegünstigung** – ein Zollvorteil für ein Land gilt für alle Mitglieder.",
    more: "Ausnahme von der Meistbegünstigung: Freihandelszonen und Zollunionen wie die EU. Weitere Grundprinzipien sind Inländerbehandlung (Importware darf nicht diskriminiert werden) und gebundene Zollobergrenzen. China trat 2001 bei, Russland 2012 – beides prägte die Globalisierung." },
  { id: "pwe-097", cat: "politik", topic: "Welthandel", type: "truefalse", emoji: "⚖️", level: 3,
    q: "Das Berufungsgremium der WTO ist seit 2019 lahmgelegt.",
    answer: true,
    explain: "Wahr. Die USA blockieren seit Jahren die Ernennung neuer Richter – Kritik an angeblicher Überdehnung von Kompetenzen begann schon unter Obama. Seit Dezember 2019 ist das Gremium nicht beschlussfähig. Wer verliert, kann „ins Leere“ Berufung einlegen. Die EU u. a. nutzen als Notlösung ein Schiedsverfahren (MPIA)." },
  { id: "pwe-098", cat: "politik", topic: "Welthandel", type: "quiz", emoji: "📊", level: 2,
    q: "Welches Land trat 2001 der WTO bei und wurde danach zur „Werkbank der Welt“?",
    options: ["Indien", "Russland", "Vietnam", "China"], answer: 3,
    explain: "Der WTO-Beitritt Chinas löste einen Exportboom aus. Ökonomen nennen die Folgen für US-Industrieregionen den **China-Schock** (Autor, Dorn, Hanson): Millionen Industriejobs gingen verloren – ein wichtiger Hintergrund für Populismus und protektionistische Politik in den USA." },
  { id: "pwe-100", cat: "politik", topic: "Welthandel", type: "quiz", emoji: "🤝", level: 2,
    q: "Was ist das Mercosur-Abkommen der EU?",
    options: ["Ein Militärbündnis mit Lateinamerika", "Ein Freihandelsabkommen mit Brasilien, Argentinien, Uruguay und Paraguay", "Ein Rohstoffvertrag mit Chile", "Ein Klimaabkommen mit Mexiko"], answer: 1,
    explain: "Nach über 25 Jahren Verhandlungen wurde Ende 2024 eine Einigung erzielt; es wäre eine der größten Freihandelszonen der Welt (rund 700 Mio. Menschen). Befürworter: Absatzmärkte für Autos, Maschinen, Zugang zu Rohstoffen. Kritiker, etwa französische Landwirte: Konkurrenz durch Agrarimporte, Umweltstandards." },
  { id: "pwe-101", cat: "politik", topic: "Welthandel", type: "whatif", emoji: "🏗️", level: 2,
    q: "Was passiert, wenn Staaten massiv eigene Industrien subventionieren (z. B. US-IRA, China-E-Autos)?",
    steps: ["Investitionen wandern ins Förderland", "Andere Staaten fühlen sich benachteiligt", "Gegen-Subventionen oder Ausgleichszölle", "Subventionswettlauf belastet Haushalte", "WTO-Regeln verlieren an Bindekraft"],
    text: "Industriepolitik ist zurück: Der US Inflation Reduction Act (2022) lockte Batterie- und Solarfabriken an, die EU antwortete u. a. mit Chips Act und Zöllen auf chinesische E-Autos. Gewinner sind kurzfristig Standorte mit tiefen Taschen, Verlierer oft kleinere Volkswirtschaften." },

  // ───────── Geopolitik-Konzepte ─────────
  { id: "pwe-102", cat: "politik", topic: "Geopolitik", type: "flashcard", emoji: "🔄", level: 1,
    term: "Sicherheitsdilemma",
    def: "Rüstet ein Staat zur eigenen Sicherheit auf, fühlen sich Nachbarn bedroht und rüsten ebenfalls auf. Am Ende sind alle weniger sicher – obwohl niemand angreifen wollte.",
    example: "Wettrüsten vor dem Ersten Weltkrieg (deutsch-britisches Flottenrennen) oder heute Aufrüstung im Indopazifik." },
  { id: "pwe-103", cat: "politik", topic: "Geopolitik", type: "fact", emoji: "🧊", level: 2,
    title: "Abschreckung: Drohen, um nicht kämpfen zu müssen",
    text: "**Abschreckung durch Bestrafung**: Ein Angriff würde unerträgliche Vergeltung auslösen. **Abschreckung durch Verweigerung**: Ein Angriff würde gar nicht erst gelingen. Beides funktioniert nur mit Fähigkeit, Willen und Glaubwürdigkeit.",
    more: "Formel zum Merken: Abschreckung = Fähigkeit × Wille × Kommunikation. Fehlt ein Faktor, ist das Produkt null. Darum stationiert die NATO Brigaden im Baltikum („Stolperdraht“): Ein Angriff träfe sofort Soldaten vieler Verbündeter – das macht das Beistandsversprechen glaubwürdig." },
  { id: "pwe-104", cat: "politik", topic: "Geopolitik", type: "quiz", emoji: "🎬", level: 1,
    q: "Was beschreibt „Soft Power“ nach Joseph Nye?",
    options: ["Einfluss durch Anziehungskraft von Kultur, Werten und Politik", "Militärische Macht mit leichten Waffen", "Wirtschaftliche Sanktionen", "Cyberangriffe ohne Todesopfer"], answer: 0,
    explain: "Soft Power heißt: Andere wollen, was man selbst will – statt Zwang (Hard Power) oder Bezahlung. Beispiele: Hollywood, Universitäten, K-Pop, Demokratie als Vorbild. China investiert stark in Soft Power (Konfuzius-Institute), tut sich aber schwer. Kombiniert spricht Nye von **Smart Power**." },
  { id: "pwe-105", cat: "politik", topic: "Geopolitik", type: "flashcard", emoji: "🌐", level: 1,
    term: "Multipolarität",
    def: "Weltordnung mit mehreren Machtzentren statt einer (unipolar) oder zwei (bipolar) Supermächten.",
    example: "Kalter Krieg: bipolar (USA vs. UdSSR). 1990er: unipolarer „Moment“ der USA. Heute: Aufstieg Chinas, Indiens, der Golfstaaten – viele sprechen von einer multipolaren Welt." },
  { id: "pwe-106", cat: "politik", topic: "Geopolitik", type: "flashcard", emoji: "🏛️", level: 3,
    term: "Thukydides-Falle",
    def: "Begriff von Graham Allison: Wenn eine aufstrebende Macht eine etablierte herausfordert, endet das oft im Krieg. Nach dem antiken Historiker Thukydides (Athen vs. Sparta).",
    example: "Allison fand in 16 historischen Fällen 12 Kriege – heute auf die USA-China-Rivalität angewandt. Kritik: Krieg ist kein Naturgesetz." },
  { id: "pwe-107", cat: "politik", topic: "Rohstoffe", type: "number", emoji: "🧲", level: 2,
    value: "≈ 90 %", label: "Chinas Anteil an der Verarbeitung Seltener Erden",
    text: "China fördert rund 60–70 % der Seltenen Erden weltweit, kontrolliert aber vor allem die Weiterverarbeitung und die Magnetproduktion fast vollständig (Stand 2025).",
    more: "Seltene Erden stecken in Elektromotoren, Windturbinen, Smartphones und Raketen. 2025 nutzte China Exportkontrollen gezielt als Druckmittel im Zollstreit mit den USA – Autohersteller meldeten Engpässe. Die Lehre: Wer die Verarbeitung kontrolliert, hat Hebel. Darum fördert die EU eigene Projekte (Critical Raw Materials Act)." },
  { id: "pwe-108", cat: "politik", topic: "Chips & Taiwan", type: "fact", emoji: "💾", level: 1,
    title: "TSMC: das wichtigste Unternehmen der Geopolitik",
    text: "Die Taiwan Semiconductor Manufacturing Company fertigt rund 90 % der modernsten Chips der Welt – für Apple, Nvidia, AMD und viele mehr. Kein anderer Ort kann sie kurzfristig ersetzen.",
    more: "Man spricht vom **„Silizium-Schutzschild“**: Taiwans Unverzichtbarkeit soll einen Angriff unattraktiv machen. Die USA (CHIPS Act) und die EU (Chips Act) holen Fabriken ins eigene Land, z. B. TSMC in Arizona und Dresden. Die Spitzentechnologie bleibt aber vorerst in Taiwan." },
  { id: "pwe-109", cat: "politik", topic: "Chips & Taiwan", type: "quiz", emoji: "🔬", level: 3,
    q: "Welches Land liefert die EUV-Lithografiemaschinen, ohne die keine Spitzenchips hergestellt werden können?",
    options: ["Japan", "USA", "Südkorea", "Niederlande"], answer: 3,
    explain: "Das niederländische Unternehmen ASML ist weltweit einziger Hersteller von EUV-Anlagen. Auf Druck der USA darf es diese nicht nach China liefern. Ein Beispiel dafür, wie Exportkontrollen auf technologische Nadelöhre zielen – und dass auch Europa Trümpfe in der Lieferkette hält." },
  { id: "pwe-110", cat: "politik", topic: "Geopolitik", type: "quiz", emoji: "⚓", level: 2,
    q: "Durch welche Meerenge läuft ein Großteil des Seehandels zwischen Nahost/Europa und Ostasien?",
    options: ["Straße von Gibraltar", "Bosporus", "Straße von Malakka", "Panamakanal"], answer: 2,
    explain: "Die Straße von Malakka zwischen Malaysia und Indonesien ist eines der wichtigsten Nadelöhre der Welt; ein großer Teil von Chinas Ölimporten fährt hindurch. Chinas Sorge vor einer Blockade dort („Malakka-Dilemma“) erklärt Pipelines und Häfen der Neuen Seidenstraße." },
  { id: "pwe-111", cat: "politik", topic: "Geopolitik", type: "flashcard", emoji: "🕵️", level: 2,
    term: "Hybride Kriegsführung",
    def: "Mix aus militärischen und nichtmilitärischen Mitteln unterhalb der Kriegsschwelle: Desinformation, Cyberangriffe, Sabotage, Erpressung mit Energie, verdeckte Truppen.",
    example: "„Grüne Männchen“ auf der Krim 2014, zerstörte Ostsee-Datenkabel, mutmaßlich gesteuerte Drohnenüberflüge über Flughäfen in Europa 2025." },
  { id: "pwe-112", cat: "politik", topic: "Geopolitik", type: "truefalse", emoji: "📚", level: 3,
    q: "Realisten erklären internationale Politik vor allem mit Macht und Sicherheit, Liberale mit Kooperation, Institutionen und Handel.",
    answer: true,
    explain: "Wahr. Realismus: Staaten leben in einer Anarchie ohne Weltpolizei, jeder sorgt für sich. Liberalismus: Interdependenz, Demokratie und Institutionen wie UN und WTO fördern Frieden. Die Wahrheit liegt oft dazwischen – die Debatte um Russlands Krieg zeigt beide Linsen." },
  { id: "pwe-113", cat: "politik", topic: "Geopolitik", type: "whatif", emoji: "🔗", level: 3,
    q: "Was passiert, wenn wirtschaftliche Abhängigkeit als Waffe eingesetzt wird?",
    steps: ["Lieferant droht mit Stopp (Gas, Rohstoffe)", "Abhängiges Land gerät unter Druck", "Kurzfristig: Kosten, Knappheit", "Mittelfristig: Diversifizierung", "Handel wird geopolitisch statt nur ökonomisch"],
    text: "Die Idee „Wandel durch Handel“ ging davon aus, dass Verflechtung Frieden stiftet. Russlands Gaspolitik und Chinas Exportkontrollen zeigen die Kehrseite: **weaponized interdependence**. Darum betonen Regierungen heute Resilienz und Versorgungssicherheit." },

  // ───────── Demokratie vs. Autokratie ─────────
  { id: "pwe-114", cat: "politik", topic: "Demokratie", type: "fact", emoji: "🗽", level: 1,
    title: "Mehr Autokratien als Demokratien",
    text: "Laut V-Dem-Institut (Göteborg) leben seit einigen Jahren mehr Menschen in Autokratien als in Demokratien – rund 70 % der Weltbevölkerung (Stand 2024/25). Das Niveau der Demokratie ist auf den Stand der späten 1980er zurückgefallen.",
    more: "Ein Grund: Große Länder wie Indien wurden von V-Dem herabgestuft (zu „Wahlautokratie“). Wichtig ist der Weg: Heute sterben Demokratien selten durch Putsche, sondern schleichend – gewählte Regierungen schwächen Gerichte, Medien und Opposition Schritt für Schritt." },
  { id: "pwe-115", cat: "politik", topic: "Demokratie", type: "flashcard", emoji: "📢", level: 1,
    term: "Populismus",
    def: "Politikstil, der die Gesellschaft in ein „reines Volk“ und eine „korrupte Elite“ teilt und beansprucht, allein den wahren Volkswillen zu vertreten (Definition nach Cas Mudde).",
    example: "Populismus gibt es links wie rechts. Problematisch für die Demokratie wird der Alleinvertretungsanspruch: Wer widerspricht, gilt als Volksfeind." },
  { id: "pwe-116", cat: "politik", topic: "Demokratie", type: "order", emoji: "🪜", level: 3,
    q: "Typischer Ablauf demokratischer Erosion (Democratic Backsliding) – bringe ihn in die Reihenfolge.",
    items: ["Regierung gewinnt freie Wahl", "Schiedsrichter werden besetzt (Gerichte, Behörden)", "Medien und Opposition werden geschwächt", "Wahlregeln werden zu eigenen Gunsten geändert"],
    explain: "Nach Levitsky/Ziblatt („Wie Demokratien sterben“): Erst die Schiedsrichter kapern, dann Gegenspieler ausschalten, dann das Spielfeld verändern. Ungarn unter Orbán gilt als Lehrbeispiel; das EU-Parlament nannte es 2022 eine „Wahlautokratie“." },
  { id: "pwe-117", cat: "politik", topic: "Demokratie", type: "quiz", emoji: "🧾", level: 3,
    q: "Was ist das „Artikel-7-Verfahren“ der EU?",
    options: ["Austrittsverfahren aus der EU", "Aufnahmeverfahren neuer Mitglieder", "Verfahren bei schwerwiegender Verletzung von EU-Grundwerten, bis zum Stimmrechtsentzug", "Verfahren gegen Staaten mit zu hohen Schulden"], answer: 2,
    explain: "Art. 7 EU-Vertrag kann im Extremfall Stimmrechte entziehen – braucht dafür aber Einstimmigkeit der übrigen Staaten. Gegen Polen und Ungarn eingeleitet, nie abgeschlossen. Wirksamer wurde der **Rechtsstaatsmechanismus** (2021): Kürzung von EU-Geldern bei Rechtsstaatsmängeln." },
  { id: "pwe-118", cat: "politik", topic: "Desinformation", type: "fact", emoji: "🤖", level: 2,
    title: "Desinformation: Zweifel säen statt überzeugen",
    text: "Staatliche Kampagnen, etwa aus Russland („Doppelgänger“: gefälschte Nachrichtenseiten), zielen selten darauf, eine Lüge glaubhaft zu machen. Ziel ist, Misstrauen in Medien, Wahlen und Institutionen zu säen und Gesellschaften zu spalten.",
    more: "Russische Propaganda nennt man „Feuerwehrschlauch der Falschheit“: viel, schnell, widersprüchlich. KI senkt die Kosten für Fakes drastisch. Gegenmittel: Medienkompetenz, Faktenchecks, Plattformregeln wie der EU **Digital Services Act**, Prebunking (vorab über Tricks aufklären)." },
  { id: "pwe-119", cat: "politik", topic: "Desinformation", type: "truefalse", emoji: "🗳️", level: 2,
    q: "In Rumänien wurde 2024 eine Präsidentschaftswahl wegen mutmaßlicher Manipulation über soziale Medien annulliert.",
    answer: true,
    explain: "Wahr. Das Verfassungsgericht annullierte im Dezember 2024 die erste Runde, nachdem der zuvor kaum bekannte Călin Georgescu mit einer massiven TikTok-Kampagne überraschend vorn lag; Geheimdienste sahen Hinweise auf ausländische Einflussnahme. Die Wahl wurde 2025 wiederholt." },

  // ───────── Internationale Justiz ─────────
  { id: "pwe-120", cat: "politik", topic: "Internationale Justiz", type: "fact", emoji: "⚖️", level: 1,
    title: "IGH vs. IStGH: Staaten vs. Personen",
    text: "Beide sitzen in Den Haag. Der **Internationale Gerichtshof (IGH)**, ein UN-Organ, entscheidet Streit zwischen **Staaten**. Der **Internationale Strafgerichtshof (IStGH)** ist eigenständig und verfolgt **Einzelpersonen** wegen Völkermord, Kriegs- und Menschlichkeitsverbrechen.",
    more: "Merkhilfe: Im IStGH steckt „**St**raf“ – er bestraft Menschen; der IGH schlichtet zwischen Staaten. Beispiele: Südafrika verklagte Israel vor dem IGH (2023); der IStGH erließ Haftbefehle gegen Putin (2023) und Netanjahu (2024)." },
  { id: "pwe-121", cat: "politik", topic: "Internationale Justiz", type: "quiz", emoji: "🔨", level: 2,
    q: "Welcher Staat ist Mitglied des Internationalen Strafgerichtshofs?",
    options: ["Deutschland", "USA", "China", "Russland"], answer: 0,
    explain: "Rund 125 Staaten sind dem Römischen Statut (1998, in Kraft 2002) beigetreten, darunter alle EU-Staaten. Nicht dabei: USA, China, Russland, Indien, Israel. Die USA verhängten 2025 sogar Sanktionen gegen IStGH-Richter und den Chefankläger." },
  { id: "pwe-122", cat: "politik", topic: "Internationale Justiz", type: "truefalse", emoji: "🧑‍⚖️", level: 2,
    q: "Der IStGH kann Prozesse auch in Abwesenheit des Angeklagten führen und verurteilen.",
    answer: false,
    explain: "Falsch. Ein Hauptverfahren setzt die Anwesenheit voraus. Der IStGH hat keine Polizei – er ist auf Mitgliedstaaten angewiesen, die Gesuchte festnehmen. Darum reist Putin kaum noch in Mitgliedstaaten; die Mongolei (2024) und Ungarn (Netanjahu, 2025) verweigerten Festnahmen." },
  { id: "pwe-123", cat: "politik", topic: "Internationale Justiz", type: "flashcard", emoji: "🧩", level: 3,
    term: "Komplementaritätsprinzip",
    def: "Der IStGH wird nur tätig, wenn ein Staat selbst nicht willens oder nicht in der Lage ist, Verbrechen ernsthaft zu verfolgen. Nationale Justiz hat Vorrang.",
    example: "Deutschland verfolgt Völkerstraftaten selbst nach dem Weltrechtsprinzip – etwa im Koblenzer Prozess gegen syrische Folterer (Urteil 2022)." },
  { id: "pwe-124", cat: "politik", topic: "Internationale Justiz", type: "event", emoji: "🏛️", year: "1945", level: 2,
    title: "Nürnberger Prozesse",
    text: "Ab November 1945 standen führende NS-Funktionäre vor einem Internationalen Militärgerichtshof. Erstmals wurden Staatsführer persönlich für Angriffskrieg und Verbrechen gegen die Menschlichkeit verurteilt.",
    more: "Nürnberg gilt als Geburtsstunde des Völkerstrafrechts: Befehl von oben schützt nicht vor Strafe. Die Idee eines ständigen Gerichts wurde erst nach den Tribunalen für Jugoslawien (1993) und Ruanda (1994) mit dem IStGH Wirklichkeit. Kritik von damals: „Siegerjustiz“." },
  { id: "pwe-125", cat: "politik", topic: "Internationale Justiz", type: "whatif", emoji: "📜", level: 3,
    q: "Was passiert, wenn der IStGH Haftbefehl gegen einen amtierenden Staatschef erlässt?",
    steps: ["125 Mitgliedstaaten müssten ihn festnehmen", "Reisen in diese Staaten werden riskant", "Diplomatische Isolation wächst", "Streit: Immunität vs. Festnahmepflicht", "Glaubwürdigkeit hängt an der Durchsetzung"],
    text: "Ohne eigene Polizei ist der IStGH auf den politischen Willen der Staaten angewiesen. Gerade deshalb sind die Fälle Putin und Netanjahu Bewährungsproben: Werden Haftbefehle selektiv ignoriert, leidet die Legitimität des Gerichts." },

  // ───────── Afrika ─────────
  { id: "pwe-126", cat: "politik", topic: "Afrika", type: "number", emoji: "👶", level: 1,
    value: "≈ 19", label: "Jahre: Medianalter in Afrika (Deutschland: ≈ 45)",
    text: "Afrika ist der jüngste Kontinent. Die Bevölkerung von rund 1,5 Mrd. dürfte laut UN bis 2050 auf rund 2,5 Mrd. wachsen – etwa jeder vierte Mensch wäre dann Afrikaner.",
    more: "Chance oder Risiko? Mit Jobs, Bildung und sinkender Kinderzahl kann eine **demografische Dividende** entstehen (wie einst in Ostasien). Ohne Jobs drohen Perspektivlosigkeit, Instabilität und Migrationsdruck. Für Europa ist Afrikas Entwicklung daher auch eine sicherheits- und wirtschaftspolitische Frage." },
  { id: "pwe-127", cat: "politik", topic: "Afrika", type: "fact", emoji: "🏜️", level: 2,
    title: "Sahel: Putschgürtel Afrikas",
    text: "Mali (2020/21), Burkina Faso (2022) und Niger (2023) erlebten Militärputsche. Die Juntas warfen französische Truppen und UN-Missionen hinaus, verließen die Westafrikanische Wirtschaftsgemeinschaft ECOWAS und gründeten die „Allianz der Sahelstaaten“.",
    more: "Hintergrund: dschihadistische Gewalt, die trotz jahrelanger internationaler Einsätze (auch der Bundeswehr in Mali bis 2023) zunahm, und antifranzösische Stimmung. Russland füllte die Lücke mit Söldnern (Wagner, später „Afrikakorps“). Die Sicherheitslage hat sich seitdem nicht verbessert." },
  { id: "pwe-128", cat: "politik", topic: "Afrika", type: "quiz", emoji: "🌍", level: 1,
    q: "Was ist die AfCFTA?",
    options: ["Afrikas Antwort auf die NATO", "Eine afrikanische Gemeinschaftswährung", "Die afrikanische Kontinentale Freihandelszone", "Ein Klimafonds der Afrikanischen Union"], answer: 2,
    explain: "Die African Continental Free Trade Area handelt seit 2021 und umfasst fast alle 55 AU-Staaten – gemessen an Mitgliedern die größte Freihandelszone der Welt. Der innerafrikanische Handel liegt nur bei rund 15 %; schlechte Infrastruktur und Bürokratie bremsen mehr als Zölle." },
  { id: "pwe-129", cat: "politik", topic: "Afrika", type: "whatif", emoji: "⛏️", level: 3,
    q: "Was passiert, wenn Rohstoffe wie Kobalt (DR Kongo) für E-Autos immer wichtiger werden?",
    steps: ["Großmächte konkurrieren um Minen und Verträge", "China dominiert bereits die Raffination", "Westen startet eigene Partnerschaften", "Chance auf Einnahmen und Verarbeitung vor Ort", "Risiko: Korruption, Konflikte, Kinderarbeit"],
    text: "Die DR Kongo liefert rund 70 % des weltweiten Kobalts. Ob Rohstoffreichtum zum Segen wird, hängt an Regierungsführung – sonst droht der „Ressourcenfluch“. Afrikanische Staaten fordern zunehmend, Wertschöpfung im Land zu halten (z. B. Simbabwes Lithium-Exportverbot für Roherz)." },
  { id: "pwe-130", cat: "politik", topic: "Afrika", type: "truefalse", emoji: "🗺️", level: 1,
    q: "Die Afrikanische Union hat 55 Mitgliedstaaten.",
    answer: true,
    explain: "Wahr – alle international anerkannten Staaten Afrikas plus die Westsahara (Sahrauische Republik). Die AU (2002, Nachfolgerin der OAU) sitzt in Addis Abeba. Mitglieder nach Putschen wie Mali, Burkina Faso, Niger oder Guinea wurden suspendiert." },

  // ───────── Atomwaffen ─────────
  { id: "pwe-131", cat: "politik", topic: "Atomwaffen", type: "number", emoji: "☢️", level: 1,
    value: "9", label: "Staaten mit Atomwaffen",
    text: "USA, Russland, China, Frankreich, Großbritannien, Indien, Pakistan, Nordkorea und (unbestätigt) Israel. Zusammen besitzen sie laut SIPRI rund 12.000 Sprengköpfe (Stand 2025).",
    more: "Russland und die USA halten zusammen knapp 90 % aller Sprengköpfe. Am schnellsten wächst Chinas Arsenal – geschätzt rund 600 Sprengköpfe, Tendenz stark steigend. Israel betreibt eine Politik der „nuklearen Ambiguität“: weder bestätigen noch dementieren." },
  { id: "pwe-132", cat: "politik", topic: "Atomwaffen", type: "fact", emoji: "📜", level: 2,
    title: "Atomwaffensperrvertrag (NVV): ein Deal in drei Säulen",
    text: "Seit 1970 in Kraft, rund 190 Vertragsstaaten. 1. Nicht-Atommächte verzichten auf Atomwaffen. 2. Die fünf offiziellen Atommächte verpflichten sich zu Abrüstungsverhandlungen. 3. Alle dürfen Kernenergie friedlich nutzen.",
    more: "Offizielle Atommächte sind nur Staaten, die vor 1967 getestet hatten – also die P5. Indien, Pakistan und Israel traten nie bei, Nordkorea trat 2003 aus. Viele Nicht-Atommächte kritisieren, dass die Abrüstungssäule kaum erfüllt wird; daraus entstand der Atomwaffenverbotsvertrag (2021, ohne Atommächte)." },
  { id: "pwe-133", cat: "politik", topic: "Atomwaffen", type: "flashcard", emoji: "💣", level: 2,
    term: "MAD – Mutually Assured Destruction",
    def: "Gegenseitig zugesicherte Zerstörung: Haben beide Seiten eine gesicherte Zweitschlagfähigkeit, würde ein Atomangriff die eigene Vernichtung bedeuten – das hält von einem Erstschlag ab.",
    example: "Grundlage der Stabilität im Kalten Krieg. U-Boote mit Atomraketen gelten als zentrale Zweitschlagwaffe, weil sie kaum aufzuspüren sind." },
  { id: "pwe-134", cat: "politik", topic: "Atomwaffen", type: "quiz", emoji: "🔧", level: 3,
    q: "Welches Land hat als einziges selbst gebaute Atomwaffen freiwillig vollständig abgebaut?",
    options: ["Südafrika", "Ukraine", "Libyen", "Brasilien"], answer: 0,
    explain: "Südafrika baute zur Apartheid-Zeit sechs Bomben und zerlegte sie Anfang der 1990er vor dem Machtwechsel. Die Ukraine, Belarus und Kasachstan gaben geerbte sowjetische Waffen ab; Libyen gab 2003 sein Programm im Anfangsstadium auf – Gaddafis späterer Sturz gilt Nordkorea als Warnung." },
  { id: "pwe-135", cat: "politik", topic: "Atomwaffen", type: "truefalse", emoji: "🇩🇪", level: 2,
    q: "In Deutschland lagern im Rahmen der nuklearen Teilhabe der NATO US-Atomwaffen.",
    answer: true,
    explain: "Wahr – nach allgemeiner Einschätzung in Büchel (Eifel), offiziell nie bestätigt. Im Ernstfall würden Bundeswehr-Kampfjets sie einsetzen, nach Freigabe durch den US-Präsidenten. Dafür kauft Deutschland F-35-Jets. Die Teilhabe gibt Nicht-Atommächten Mitsprache in der nuklearen Planung." },
  { id: "pwe-136", cat: "politik", topic: "Atomwaffen", type: "order", emoji: "⏳", level: 2,
    q: "Bringe die nuklearen Wegmarken in die richtige Reihenfolge.",
    items: ["Hiroshima und Nagasaki", "Kubakrise", "Atomwaffensperrvertrag tritt in Kraft", "Ende des INF-Vertrags über Mittelstreckenwaffen"],
    explain: "1945 einzige Kriegseinsätze, 1962 Kubakrise (Welt am Abgrund, danach „heißer Draht“), 1970 NVV, 2019 Ende des INF-Vertrags (USA stiegen wegen russischer Verstöße aus). New START, das letzte große US-russische Abkommen, lief im Februar 2026 aus." },
  { id: "pwe-137", cat: "politik", topic: "Atomwaffen", type: "whatif", emoji: "🌋", level: 3,
    q: "Was passiert, wenn Iran die Atombombe baut?",
    steps: ["Israel sieht existenzielle Bedrohung", "Hohes Risiko präventiver Militärschläge", "Saudi-Arabien kündigte eigene Bombe an", "Regionales nukleares Wettrüsten droht", "NVV verliert weiter an Autorität"],
    text: "Genau diese Kaskade fürchten Fachleute: Saudi-Kronprinz Mohammed bin Salman sagte 2018, man werde nachziehen, falls Iran die Bombe bekommt. Auch Türkei und Ägypten könnten folgen. Nichtverbreitung lebt davon, dass ein Ausreißer keine Kettenreaktion auslöst." },
  { id: "pwe-138", cat: "politik", topic: "Atomwaffen", type: "quiz", emoji: "🇰🇵", level: 1,
    q: "Welcher Staat ist als einziger aus dem Atomwaffensperrvertrag ausgetreten?",
    options: ["Iran", "Indien", "Pakistan", "Nordkorea"], answer: 3,
    explain: "Nordkorea erklärte 2003 den Austritt und testete 2006 erstmals eine Atombombe, bis 2017 folgten fünf weitere Tests. Indien und Pakistan waren nie Mitglied, Iran ist Mitglied – hat aber mit Austritt gedroht." },
);
